using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Cosmos provider no longer supports HasIndex (throws at runtime in 9.0).
        // Indexes are managed by Cosmos DB itself; remove the HasIndex call.

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // To read existing documents that use "Discriminator", restore the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|KeyValue" to just "KeyValue" in 9.0.
        // To read existing documents with the old "Blog|1" format, opt back in.
        modelBuilder.Entity<Blog>().HasPartitionKey(e => e.Id);
        modelBuilder.Entity<Blog>().Property(e => e.Id)
            .HasJsonPropertyName("id");
    }
}

// Breaking change 4: In 9.0, sync I/O throws by default. Either:
//   (a) switch to async APIs (ToListAsync, SaveChangesAsync), or
//   (b) opt in via .EnableSyncApiSupport() in OnConfiguring.
// See SyncJob.cs for the async fix.

class Blog { public string Id { get; set; } public string Name { get; set; } }

